"""Vietnamese editorial copy for core scene workflows."""

COMMON={'CAMERA WORKFLOW':'QUY TRÌNH GHI HÌNH BẰNG CAMERA','YOUTUBE WORKFLOW':'QUY TRÌNH VIDEO YOUTUBE','PRESENTATION WORKFLOW':'QUY TRÌNH THUYẾT TRÌNH','The workflow this page is built for':'Tình huống mà trang này hướng đến','From script to finished delivery':'Từ kịch bản đến phần trình bày hoàn chỉnh','Recommended CuePrompt settings':'Thiết lập CuePrompt đề xuất','A script structure that fits':'Cấu trúc kịch bản phù hợp','Common mistakes to avoid':'Những lỗi thường gặp cần tránh','Questions before you start':'Câu hỏi trước khi bắt đầu','Open camera teleprompter':'Mở teleprompter có camera','Compress a finished take':'Nén bản ghi hình','Start a YouTube script':'Tạo kịch bản YouTube','Use the YouTube 16:9 preset':'Dùng thiết lập YouTube 16:9','Prepare publishing copy':'Chuẩn bị nội dung xuất bản','Start a presentation script':'Tạo kịch bản thuyết trình','Rehearse in full screen':'Luyện tập toàn màn hình'}

CAMERA=(
('Reading from notes usually pulls your eyes away from the lens, while separate camera and prompting apps add setup and file-transfer work. CuePrompt keeps the script, camera preview and recording controls in one browser tab.','Đọc ghi chú thường khiến mắt rời khỏi ống kính, còn dùng riêng ứng dụng camera và teleprompter làm tăng công việc thiết lập và chuyển tệp. CuePrompt đặt kịch bản, màn hình xem trước và điều khiển ghi hình trong cùng một thẻ trình duyệt.'),
('Paste or write the script, then break long paragraphs into lines you can say in one breath.','Dán hoặc viết kịch bản, sau đó chia đoạn dài thành những câu có thể nói tự nhiên trong một nhịp thở.'),
('Open Camera & record, frame the shot and place the reading area close to the lens.','Mở Camera và ghi hình, căn khung rồi đặt vùng đọc gần ống kính.'),
('Run a short test, check sound and eye line, then record the full take and download it locally.','Quay thử một đoạn ngắn, kiểm tra âm thanh và hướng nhìn, sau đó ghi hình đầy đủ và lưu trên thiết bị.'),
('Mirror the preview when it helps you frame naturally.','Lật gương phần xem trước nếu điều đó giúp bạn căn khung tự nhiên hơn.'),
('Start with larger text and a comfortable steady speed; switch to Smart Follow when supported.','Bắt đầu với chữ lớn và tốc độ đều, thoải mái; chuyển sang Smart Follow khi trình duyệt hỗ trợ.'),
('Use [pause] before important points and [slow] where the delivery should settle.','Thêm [pause] trước ý quan trọng và [slow] ở chỗ cần nói chậm, bình tĩnh hơn.'),
('Hook → one clear idea → supporting example → next action.','Câu mở đầu → một ý rõ ràng → ví dụ hỗ trợ → hành động tiếp theo.'),
('“If your eyes keep dropping to notes, put the words beside the lens. [pause] Keep each thought short, speak it naturally, then look back at the viewer.”','“Nếu mắt bạn liên tục nhìn xuống ghi chú, hãy đặt lời thoại cạnh ống kính. [pause] Giữ từng ý ngắn gọn, nói tự nhiên rồi nhìn lại người xem.”'),
('Recording the first take without checking microphone input.','Ghi hình lần đầu mà chưa kiểm tra đầu vào micro.'),
('Putting the prompt far from the lens and creating obvious side-to-side eye movement.','Đặt lời nhắc xa ống kính khiến mắt di chuyển ngang quá rõ.'),
('Using dense paragraphs that are hard to scan while speaking.','Dùng đoạn văn dày đặc, khó đọc lướt trong khi nói.'),
('Is the recording uploaded?','Bản ghi có được tải lên không?'),
('No. Camera recording is created in your browser and remains on your device unless you choose to share or upload the downloaded file.','Không. Bản ghi được tạo trong trình duyệt và nằm trên thiết bị, trừ khi bạn chủ động chia sẻ hoặc tải tệp đã lưu lên.'),
('Why does the camera need HTTPS?','Tại sao camera cần HTTPS?'),
('Browsers require a secure page before granting camera and microphone access.','Trình duyệt yêu cầu một trang an toàn trước khi cấp quyền truy cập camera và micro.'),
('Should I mirror the final video?','Có nên lật gương video cuối cùng không?'),
('Mirror is mainly a preview preference. Review the downloaded take before publishing, especially when signs or text appear in frame.','Lật gương chủ yếu là tùy chọn xem trước. Hãy kiểm tra bản ghi đã tải xuống trước khi xuất bản, nhất là khi trong khung có biển hiệu hoặc chữ.'),)

YOUTUBE=(
('Long-form YouTube videos need more than continuous scrolling: the opening must establish a promise, sections must stay easy to navigate, and the speaker still needs natural eye contact. CuePrompt connects a structured script, rehearsal, recording and publishing handoff.','Video YouTube dài cần nhiều hơn việc cuộn liên tục: phần mở đầu phải cho biết người xem nhận được gì, các phần phải dễ theo dõi và ánh mắt vẫn cần tự nhiên. CuePrompt kết nối kịch bản có cấu trúc, luyện tập, ghi hình và chuẩn bị xuất bản.'),
('Start with the YouTube template and define the viewer, promise and three main sections.','Bắt đầu với mẫu YouTube, xác định người xem, kết quả đã hứa và ba phần chính.'),
('Use ## headings to separate chapters, then rehearse each section with Smart Follow or steady scrolling.','Dùng tiêu đề ## để tách chương, rồi luyện từng phần với Smart Follow hoặc cuộn đều.'),
('Record in landscape, review the take, and prepare the title, description, tags and captions before upload.','Ghi hình ngang, xem lại bản quay và chuẩn bị tiêu đề, mô tả, thẻ cùng phụ đề trước khi tải lên.'),
('Choose a landscape 16:9 export for a standard YouTube video.','Chọn xuất ngang 16:9 cho video YouTube tiêu chuẩn.'),
('Keep the prompt close to the lens and use a readable size that avoids rapid eye movement.','Đặt lời nhắc gần ống kính và dùng cỡ chữ dễ đọc để mắt không phải di chuyển nhanh.'),
('Add [pause] between chapters so edits and chapter transitions have clean space.','Thêm [pause] giữa các chương để có khoảng trống rõ ràng cho việc biên tập và chuyển cảnh.'),
('Hook and viewer promise → context → three useful chapters → recap → subscribe or next-video action.','Câu mở đầu và lời hứa với người xem → bối cảnh → ba chương hữu ích → tóm tắt → đăng ký hoặc xem video tiếp theo.'),
('“By the end of this video, you will have a three-step workflow you can use today. [pause] First, let’s remove the part that wastes the most time.”','“Cuối video này, bạn sẽ có quy trình ba bước để áp dụng ngay hôm nay. [pause] Trước tiên, hãy loại bỏ phần tốn nhiều thời gian nhất.”'),
('Opening with a long introduction before explaining the viewer benefit.','Mở đầu bằng phần giới thiệu dài trước khi nói rõ lợi ích cho người xem.'),
('Writing one uninterrupted block instead of visible chapters.','Viết một khối nội dung liên tục thay vì chia chương rõ ràng.'),
('Reading every sentence at the same pace and losing conversational emphasis.','Đọc mọi câu cùng một tốc độ và làm mất nhấn nhá tự nhiên của hội thoại.'),
('Can I create chapter-ready scripts?','Có thể tạo kịch bản sẵn sàng chia chương không?'),
('Yes. Use ## headings for the major sections, then carry those section names into your YouTube chapter plan.','Có. Dùng tiêu đề ## cho các phần chính, sau đó dùng tên các phần đó trong kế hoạch chương YouTube.'),
('What format should I export?','Nên xuất định dạng nào?'),
('For a standard horizontal video, the local converter provides a YouTube 16:9 MP4 preset.','Với video ngang tiêu chuẩn, công cụ chuyển đổi cục bộ cung cấp thiết lập MP4 YouTube 16:9.'),
('How do I sound less scripted?','Làm sao để giọng nói bớt giống đọc kịch bản?'),
('Write short spoken sentences, rehearse once, and treat the prompt as a guide rather than forcing every word into one take.','Viết câu nói ngắn, luyện tập một lần và dùng lời nhắc như hướng dẫn thay vì cố nói chính xác từng từ trong một lần quay.'),)

PRESENTATIONS=(
('A presentation can lose momentum when the speaker memorizes every line or keeps looking down at notes. A teleprompter works best as a speaking outline: clear transitions, intentional pauses and a readable full-screen view.','Bài thuyết trình có thể mất nhịp khi người nói học thuộc từng dòng hoặc liên tục nhìn xuống ghi chú. Teleprompter hiệu quả nhất khi dùng như dàn ý nói, với chuyển ý rõ ràng, khoảng dừng có chủ đích và chế độ toàn màn hình dễ đọc.'),
('Choose the speech template and turn each slide or idea into one short speaking section.','Chọn mẫu bài nói và biến mỗi trang chiếu hoặc ý tưởng thành một phần trình bày ngắn.'),
('Mark transitions with ## headings and add [pause] after key claims, questions or slide changes.','Đánh dấu chuyển ý bằng tiêu đề ## và thêm [pause] sau luận điểm chính, câu hỏi hoặc khi đổi trang chiếu.'),
('Rehearse in full screen, adjust text size for the viewing distance and time the complete talk.','Luyện tập toàn màn hình, chỉnh cỡ chữ theo khoảng cách nhìn và đo thời lượng toàn bộ bài nói.'),
('Use full-screen reading and increase text size when the display is farther away.','Đọc toàn màn hình và tăng cỡ chữ khi màn hình ở xa.'),
('Choose steady scrolling for a fixed rehearsal pace or Smart Follow when you need flexible pauses.','Chọn cuộn đều để giữ nhịp cố định hoặc Smart Follow khi cần khoảng dừng linh hoạt.'),
('Keep controls accessible and test the same browser, display and connection used at the event.','Đặt điều khiển trong tầm với và kiểm tra đúng trình duyệt, màn hình cùng kết nối sẽ dùng tại sự kiện.'),
('Opening idea → audience relevance → three supporting points → memorable recap → clear closing.','Ý mở đầu → sự liên quan với khán giả → ba luận điểm hỗ trợ → tóm tắt đáng nhớ → kết thúc rõ ràng.'),
('“Here is the question I want us to keep in mind today. [pause] What would change if this process took minutes instead of hours?”','“Đây là câu hỏi tôi muốn chúng ta ghi nhớ hôm nay. [pause] Điều gì sẽ thay đổi nếu quy trình này chỉ mất vài phút thay vì nhiều giờ?”'),
('Copying slide text word for word instead of writing natural transitions.','Sao chép nguyên văn trang chiếu thay vì viết câu chuyển ý tự nhiên.'),
('Using text that is too small for the distance between speaker and display.','Dùng chữ quá nhỏ so với khoảng cách giữa người nói và màn hình.'),
('Skipping a full rehearsal with the actual presentation setup.','Bỏ qua buổi luyện tập đầy đủ với thiết bị trình chiếu thực tế.'),
('Can I use CuePrompt for a speech without slides?','Có thể dùng CuePrompt cho bài nói không có trang chiếu không?'),
('Yes. Organize the talk with headings, pauses and a strong closing, then read in full screen.','Có. Hãy tổ chức bài nói bằng tiêu đề, khoảng dừng và phần kết mạnh, rồi đọc ở chế độ toàn màn hình.'),
('How should I rehearse slide changes?','Nên luyện chuyển trang chiếu thế nào?'),
('Add a heading or [pause] marker at every transition and practice advancing the slide during that space.','Thêm tiêu đề hoặc [pause] tại mỗi điểm chuyển và luyện đổi trang chiếu trong khoảng dừng đó.'),
('Does it work on a tablet?','CuePrompt có hoạt động trên máy tính bảng không?'),
('CuePrompt works in modern mobile, tablet and desktop browsers. Test full screen and controls on the exact device before the event.','CuePrompt hoạt động trong các trình duyệt hiện đại trên điện thoại, máy tính bảng và máy tính. Hãy kiểm tra toàn màn hình cùng điều khiển trên đúng thiết bị trước sự kiện.'),)

def localize(page,locale,slug):
 packs={'teleprompter-with-camera':CAMERA,'teleprompter-for-youtube':YOUTUBE,'teleprompter-for-presentations':PRESENTATIONS}
 if locale!='vi' or slug not in packs:return page
 for source,target in sorted((*COMMON.items(),*packs[slug]),key=lambda item:len(item[0]),reverse=True):page=page.replace(source,target)
 return page
